+
+                        try (XContentBuilder builder = XContentFactory.jsonBuilder()) {
+                            builder.startObject();
+                            {
+                                builder.field(SYNONYMS_FIELD, synonymRule.synonym());
+                                builder.field(SYNONYMS_SET_FIELD, resourceName);
